test.fill_query:
INSERT INTO json_squash_src_burst{burst}_rows{block_rows}
SELECT number, concat('{{', arrayStringConcat(arrayMap(i -> concat('"k', toString((intDiv(number, {burst}) * 8 + i) % 256), '":',
    if((number + i) % 3 = 0, concat('"s', toString(number), '"'), toString(number + i))), range(8)), ','), '}}')
FROM numbers(65536)
SETTINGS max_threads = 1, max_insert_threads = 1, max_block_size = {block_rows}, max_insert_block_size = {block_rows},
    min_insert_block_size_rows = {block_rows}, min_insert_block_size_bytes = 0
